import
{
    Routes
}
from '@angular/router';


//===========================================================
// MNU-008-002 Routes
//===========================================================

export const mnu008002Routes:
Routes =
[


    //===========================================================
    // Menu Routes
    //===========================================================
    // Auto-generated by Menu Synchronization Engine.
    // Submenu Synchronization Engine will register:
    //   • Submenu routes
    //   • Activity routes
    //   • Page routes
    //===========================================================


    {
        path:'',

        children:
        [

            // SUBMENU ROUTE PLACEHOLDER

            //===========================================================
            // Bike Deliveries (hand-wired : hand-written page, NEVER run
            // Code Sync for it)
            //===========================================================
            {
                path:'bike-deliveries',
                data:
                {
                    breadcrumb:'Bike Deliveries'
                },
                loadChildren:() =>
                    import(
                        './bike-deliveries.routes'
                    )
                    .then(
                        m =>
                            m.BikeDeliveriesRoutes
                    )
            },

            //===========================================================
            // Sales Quotations - MB (hand-wired : the shared Sales
            // Invoice page in quotation mode; NEVER Code Sync)
            //===========================================================
            {
                path:'sales-quotations-mb',

                data:
                {
                    breadcrumb:'Sales Quotations - MB'
                },

                loadChildren:() =>
                    import(
                        './sales-quotations-mb.routes'
                    )
                    .then(
                        m =>
                            m.SalesQuotationsMbRoutes
                    )
            },

            //===========================================================
            // Sales Returns - MB (hand-wired : the shared Sales Return
            // pages; NEVER Code Sync)
            //===========================================================

            {
                path:'sales-returns-mb',

                data:
                {
                    breadcrumb:'Sales Returns - MB'
                },

                loadChildren:() =>
                    import(
                        './sales-returns-mb.routes'
                    )
                    .then(
                        m =>
                            m.SalesReturnsMbRoutes
                    )
            },


            //===========================================================
            // Sales Invoices - MB (hand-wired : the shared Sales
            // Invoice pages)
            //===========================================================

            {
                path:'sales-invoices-mb',

                data:
                {
                    breadcrumb:'Sales Invoices - MB'
                },

                loadChildren:() =>
                    import(
                        './sales-invoices-mb.routes'
                    )
                    .then(
                        m =>
                            m.SalesInvoicesMbRoutes
                    )
            },

        ]

    }

];